using System;using UnityEngine.InputSystem;using UnityEngine.InputSystem.LowLevel;namespace Mojinloop.InputActivity{public sealed class EditorInputActivitySource:IGlobalInputActivitySource{public event Action ActivityDetected;public void StartListening()=>InputSystem.onEvent+=OnEvent;public void StopListening()=>InputSystem.onEvent-=OnEvent;void OnEvent(InputEventPtr e,InputDevice d){if((e.IsA<StateEvent>()||e.IsA<DeltaStateEvent>())&&(d is Keyboard||d is Mouse))ActivityDetected?.Invoke();}}}
